const template03Meta_hbs = "<title>Standard Article Template</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Dela+Gothic+One&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');\n\n  :root{\n    --blue:#2D2DFF;\n    --blue-hover:#0000CC;\n    --black:#0A0A0A;\n    --surface:#111111;\n    --grey:#8C8C8C;\n    --white:#FFFFFF;\n    --border:#FFFFFF;\n    --hairline:rgba(255,255,255,0.14);\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{\n    background:var(--black);\n    color:var(--white);\n    font-family:'Space Grotesk',sans-serif;\n    line-height:1.65;\n    -webkit-font-smoothing:antialiased;\n  }\n  ::selection{background:var(--blue);color:var(--white);}\n  h1,h2,h3{margin:0;text-wrap:balance;}\n  p{margin:0;}\n  a{color:inherit;text-decoration:none;}\n  img,svg{display:block;max-width:100%;}\n  .wrap{max-width:1180px;margin:0 auto;padding-inline:24px;}\n  @media(min-width:900px){.wrap{padding-inline:80px;}}\n  @media(min-width:1440px){.wrap{padding-inline:96px;}}\n\n  .grid-tex{\n    position:absolute;inset:0;\n    background-image:\n      linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),\n      linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px);\n    background-size:32px 32px;\n    pointer-events:none;\n  }\n\n  /* Header/footer are intentionally not part of this output — the article\n     is meant to be embedded into the real EDT site/CMS, which supplies its\n     own. .btn/.btn-primary/.btn-ghost/.arrow are kept: the dynamic CTA\n     section at the bottom still uses them. */\n  .btn{\n    display:inline-flex;align-items:center;gap:9px;\n    font-family:'Space Grotesk',sans-serif;font-weight:600;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;\n    padding:13px 22px;border:1px solid var(--blue);\n    transition:background 120ms ease,color 120ms ease,transform 120ms ease;\n  }\n  .btn-primary{background:var(--blue);color:var(--white);}\n  .btn-primary:hover{background:var(--blue-hover);transform:scale(1.02);}\n  .btn-ghost{background:transparent;border-color:var(--white);}\n  .btn-ghost:hover{background:var(--white);color:var(--black);}\n  .arrow{transition:transform 120ms ease;display:inline-block;}\n  .btn:hover .arrow{transform:translateX(3px);}\n\n  /* ================= CRUMB ================= */\n  .crumb-bar{border-bottom:1px solid var(--hairline);}\n  .crumb-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--grey);}\n  .crumb-row .sep{color:var(--blue);margin:0 8px;}\n  .template-tag{border:1px solid var(--blue);color:var(--blue);padding:3px 9px;font-weight:600;}\n\n  /* ================= ARTICLE HERO ================= */\n  .article-hero{position:relative;overflow:hidden;padding:56px 0 40px;}\n  .eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;letter-spacing:0.14em;text-transform:uppercase;color:var(--blue);margin-bottom:20px;}\n  .eyebrow::before{content:\"\";width:8px;height:8px;background:var(--blue);}\n  h1.title{\n    font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;letter-spacing:-0.02em;\n    font-size:clamp(32px,6vw,60px);line-height:1.05;max-width:22ch;\n  }\n  .dek{margin-top:22px;max-width:62ch;font-size:clamp(16px,1.8vw,19px);color:#cfcfcf;font-weight:300;}\n  .byline-row{margin-top:32px;display:flex;flex-wrap:wrap;border-top:1px solid var(--hairline);}\n  .byline-item{flex:1 1 130px;padding:14px 20px;border-right:1px solid var(--hairline);}\n  .byline-item:first-child{padding-left:0;}\n  .byline-item:last-child{border-right:none;}\n  .byline-item .k{font-size:10px;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);margin-bottom:5px;}\n  .byline-item .v{font-size:13px;font-weight:500;}\n\n  /* ================= LAYOUT: BODY + TOC ================= */\n  .article-layout{padding:8px 0 32px;}\n  .layout-grid{display:grid;grid-template-columns:1fr;gap:48px;}\n  @media(min-width:980px){\n    .layout-grid{grid-template-columns:190px 1fr;gap:56px;align-items:start;}\n  }\n\n  /* ---- TOC ---- */\n  .toc-wrap{border:1px solid var(--hairline);background:var(--surface);order:-1;}\n  @media(min-width:980px){\n    .toc-wrap{position:sticky;top:24px;order:0;}\n  }\n  .toc-head{\n    display:flex;align-items:center;justify-content:space-between;\n    padding:12px 16px;border-bottom:1px solid var(--hairline);\n  }\n  .toc-head span{font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--grey);}\n  .toc-list{list-style:none;margin:0;padding:8px 0;}\n  .toc-list li{margin:0;}\n  .toc-list a{\n    display:flex;gap:8px;align-items:baseline;\n    padding:9px 14px;font-size:12.5px;line-height:1.4;color:var(--grey);\n    border-left:2px solid transparent;transition:color .2s ease, border-color .2s ease;\n  }\n  .toc-list a .n{font-size:10px;color:var(--grey);flex-shrink:0;}\n  .toc-list a:hover{color:var(--white);}\n  .toc-list a.active{color:var(--white);border-left-color:var(--blue);background:rgba(45,45,255,0.08);}\n  .toc-list a.active .n{color:var(--blue);}\n  .toc-progress{height:2px;background:var(--hairline);}\n  .toc-progress-bar{height:100%;width:0%;background:var(--blue);transition:width 120ms linear;}\n\n  /* ---- Article body ---- */\n  .article-main{min-width:0;}\n  .lede{font-size:18px;font-weight:400;color:#e8e8e8;margin-bottom:40px;line-height:1.7;max-width:70ch;}\n  .article-section{padding:40px 0;border-top:1px solid var(--hairline);scroll-margin-top:24px;}\n  .article-section:first-child{border-top:none;padding-top:0;}\n  .article-section h2{\n    font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:clamp(22px,2.6vw,28px);margin-bottom:18px;\n  }\n  .article-section p{font-size:16px;color:#d6d6d6;font-weight:300;line-height:1.8;margin-bottom:20px;max-width:70ch;}\n  .article-section p:last-child{margin-bottom:0;}\n  .article-section ul{margin:0 0 20px;padding-left:0;list-style:none;max-width:70ch;}\n  .article-section ul li{\n    position:relative;padding-left:22px;margin-bottom:12px;font-size:16px;color:#d6d6d6;font-weight:300;line-height:1.7;\n  }\n  .article-section ul li::before{content:\"→\";position:absolute;left:0;color:var(--blue);font-weight:700;}\n\n  /* ---- comparison table ---- */\n  .table-scroll{overflow-x:auto;margin:8px 0 28px;border:1px solid var(--hairline);}\n  table{width:100%;border-collapse:collapse;min-width:520px;font-size:14px;}\n  th,td{padding:14px 16px;text-align:left;border-bottom:1px solid var(--hairline);}\n  thead th{\n    background:var(--surface);font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:var(--blue);\n    font-weight:700;border-bottom:1px solid var(--border);\n  }\n  tbody td{color:#d6d6d6;font-weight:300;}\n  tbody td:first-child{color:var(--white);font-weight:500;}\n  tbody tr:last-child td{border-bottom:none;}\n\n  .callout{\n    margin:32px 0;padding:20px 24px;border:1px solid var(--blue);background:rgba(45,45,255,0.06);max-width:70ch;\n  }\n  .callout .label{font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--blue);margin-bottom:8px;display:block;}\n  .callout p{margin-bottom:0;color:#e8e8e8;}\n\n  .closing{padding-top:8px;}\n  .closing p{font-size:16px;color:#d6d6d6;font-weight:300;line-height:1.8;max-width:70ch;}\n\n  /* ================= CTA ================= */\n  .cta{padding:88px 0;border-top:1px solid var(--hairline);margin-top:32px;}\n  .cta h2{font-family:'Dela Gothic One',sans-serif;text-transform:uppercase;font-size:clamp(28px,5vw,48px);letter-spacing:-0.02em;max-width:16ch;margin-bottom:18px;}\n  .cta p{color:var(--grey);font-size:16px;max-width:52ch;margin-bottom:32px;font-weight:300;}\n  .cta-btns{display:flex;flex-wrap:wrap;gap:16px;}\n</style>\n\n<div class=\"crumb-bar\">\n  <div class=\"wrap crumb-row\">\n    <div><a href=\"#\">Blog</a><span class=\"sep\">/</span><a href=\"#\">{{category}}</a></div>\n    <div class=\"template-tag\">Template 03 — Standard article</div>\n  </div>\n</div>\n\n<section class=\"article-hero\">\n  <div class=\"grid-tex\" style=\"opacity:.5\"></div>\n  <div class=\"wrap\" style=\"position:relative;\">\n    <div class=\"eyebrow\">{{eyebrowText}}</div>\n    <h1 class=\"title\">{{title}}</h1>\n    <p class=\"dek\">{{dek}}</p>\n    <div class=\"byline-row\">\n      <div class=\"byline-item\"><div class=\"k\">Author</div><div class=\"v\">{{authorLabel}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Category</div><div class=\"v\">{{category}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Read time</div><div class=\"v\">{{readTimeLabel}}</div></div>\n      <div class=\"byline-item\"><div class=\"k\">Published</div><div class=\"v\">{{publishedLabel}}</div></div>\n    </div>\n  </div>\n</section>\n\n<section class=\"article-layout\">\n  <div class=\"wrap layout-grid\">\n\n    <aside class=\"toc-wrap\">\n      <div class=\"toc-head\"><span>On this page</span></div>\n      <div class=\"toc-progress\"><div class=\"toc-progress-bar\" id=\"tocProgress\"></div></div>\n      <ul class=\"toc-list\" id=\"tocList\">\n        {{#each tocSections}}\n        <li><a href=\"#{{this.anchor}}\"><span class=\"n\">{{pad2 @index}}</span>{{this.heading}}</a></li>\n        {{/each}}\n      </ul>\n    </aside>\n\n    <div class=\"article-main\">\n      <p class=\"lede\">{{lede}}</p>\n\n      {{#each bodyItems}}\n      {{#if (eq this.type \"section\")}}\n      <div class=\"article-section\" id=\"{{this.anchor}}\">\n        <h2>{{this.heading}}</h2>\n        {{#each this.blocks}}\n        {{{renderBlock this}}}\n        {{/each}}\n      </div>\n      {{else}}\n      {{{renderCallout this}}}\n      {{/if}}\n      {{/each}}\n\n      {{#if (eq galleryPlacement \"mid-article\")}}\n      {{{galleryHtml}}}\n      {{/if}}\n\n    </div>\n  </div>\n</section>\n\n{{#if (eq galleryPlacement \"before-cta\")}}\n{{{galleryHtml}}}\n{{/if}}\n\n{{#if cta}}\n<section class=\"cta\">\n  <div class=\"wrap\">\n    <h2>{{cta.heading}}</h2>\n    <p>{{cta.body}}</p>\n    <div class=\"cta-btns\">\n      <a class=\"btn btn-primary\" href=\"#\">Get a quote<span class=\"arrow\">→</span></a>\n      <a class=\"btn btn-ghost\" href=\"#\">See our work<span class=\"arrow\">→</span></a>\n    </div>\n  </div>\n</section>\n{{/if}}\n\n<script>\n  var links = Array.prototype.slice.call(document.querySelectorAll('#tocList a'));\n  var sections = links.map(function(a){ return document.querySelector(a.getAttribute('href')); });\n  var progressBar = document.getElementById('tocProgress');\n\n  function setActive(id){\n    links.forEach(function(a){\n      a.classList.toggle('active', a.getAttribute('href') === '#' + id);\n    });\n  }\n\n  // Scroll via scrollIntoView rather than relying on the browser's native\n  // same-page anchor navigation: when this article is shown inside a\n  // sandboxed preview iframe with only allow-scripts (no allow-same-origin\n  // — deliberately, so the frame can't reach into the host page), native\n  // fragment navigation is unreliable — it can silently no-op, or in some\n  // configurations blank the frame entirely. A direct DOM scroll sidesteps\n  // that altogether and works the same standalone or embedded.\n  links.forEach(function(a){\n    a.addEventListener('click', function(event){\n      var target = document.querySelector(a.getAttribute('href'));\n      if (!target) return;\n      event.preventDefault();\n      target.scrollIntoView({ behavior: 'smooth', block: 'start' });\n      setActive(target.id);\n    });\n  });\n\n  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n    var io = new IntersectionObserver(function(entries){\n      entries.forEach(function(entry){\n        if (entry.isIntersecting) setActive(entry.target.id);\n      });\n    }, { rootMargin: '-15% 0px -70% 0px' });\n    sections.forEach(function(s){ if (s) io.observe(s); });\n  }\n\n  function updateProgress(){\n    var h = document.documentElement;\n    var max = h.scrollHeight - h.clientHeight;\n    progressBar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';\n  }\n  document.addEventListener('scroll', updateProgress, { passive: true });\n  updateProgress();\n</script>\n";
const template03Meta_exampleJson = "{\n  \"title\": \"AR, VR OR MIXED REALITY: WHICH ONE ACTUALLY FITS YOUR EVENT?\",\n  \"dek\": \"A practical guide to picking the right immersive format before you brief a vendor — what each one is good at, what it costs, and the questions that save you a rebuild.\",\n  \"category\": \"Insights\",\n  \"readTimeMinutes\": 8,\n  \"lede\": \"Most format decisions get made backwards — a client picks \\\"VR\\\" or \\\"AR\\\" because it's the word that came up in the meeting, then briefs a vendor to make it work. Flip that order and the decision gets much easier: start from what the audience needs to walk away with, and the format usually picks itself.\",\n  \"bodyItems\": [\n    {\n      \"type\": \"section\",\n      \"heading\": \"Start with the outcome, not the tech\",\n      \"navLabel\": \"Start with the outcome\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Before naming a format, answer one question: does this need to happen on a real, physical thing the audience is standing in front of, or does it need to happen somewhere that doesn't exist yet? That single split does most of the filtering. A product reveal happening on a real stage in front of a real crowd is a different brief than a training scenario that needs a space no one can safely build in real life.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Everything below assumes you've answered that question first. If you haven't, the comparison table further down won't help much — it'll just make three options sound equally plausible.\"\n        }\n      ]\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"What AR is actually good for\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Augmented reality earns its keep when the real environment is doing half the work. It's layering — information, characters, or effects placed on top of something that's already there: a product on a shelf, a building on a heritage trail, a mascot on an event floor. AR works best when you want the audience to keep their attention split between the real world and the layer you've added, not fully replace one with the other.\"\n        },\n        {\n          \"kind\": \"bulletList\",\n          \"items\": [\n            \"Product try-on and visualisation, where seeing it on yourself or your own space is the point\",\n            \"Heritage and wayfinding trails, where the physical location carries meaning AR can't replace\",\n            \"Event activations with high foot traffic, since AR needs no headset queue to run\"\n          ]\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"What VR is actually good for\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Virtual reality earns its keep when the real environment is the problem, not the asset. Training scenarios that are too dangerous, too expensive, or physically impossible to stage for real — an earthquake, a forklift accident, a factory floor that doesn't exist yet — are where VR stops being a novelty and starts being the only practical way to rehearse something.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"It's also the strongest option when you want full control over pacing and attention: no ambient noise, no distractions, one person fully inside one experience at a time. That control is a feature for training and a limitation for large-crowd events, where a headset queue caps how many people you can move through in a day.\"\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"What mixed reality adds\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"Mixed reality sits between the two — digital objects that don't just sit on top of the real world but respond to it, aware of the room's geometry and the people in it. It's the right call when the brief genuinely needs both halves at once: a real presenter interacting with a virtual object the whole room can see respond to touch, or a hybrid broadcast where a virtual set has to react to a live physical performer.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"It's also the format most likely to be over-specified. If the brief doesn't actually need real and virtual elements to interact, mixed reality adds cost and complexity that AR or VR alone would have solved more simply.\"\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"callout\",\n      \"label\": \"EDT's rule of thumb\",\n      \"body\": \"If you can describe the experience without using the word \\\"immersive,\\\" you probably know which format you need already. If the word \\\"immersive\\\" is doing all the work in your brief, that's usually a sign the outcome hasn't been defined yet — and no format fixes that on its own.\"\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"Side-by-side comparison\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"A rough guide — real numbers depend on scope, but this is the shape of the trade-off we walk clients through first.\"\n        },\n        {\n          \"kind\": \"comparisonTable\",\n          \"columns\": [\n            \"Format\",\n            \"Best for\",\n            \"Hardware\",\n            \"Crowd throughput\"\n          ],\n          \"rows\": [\n            [\n              \"AR\",\n              \"Layering onto a real product, place, or person\",\n              \"Phone or tablet\",\n              \"High — no queue needed\"\n            ],\n            [\n              \"VR\",\n              \"Scenarios too costly or dangerous to stage for real\",\n              \"Headset, per person\",\n              \"Low — one person at a time\"\n            ],\n            [\n              \"Mixed reality\",\n              \"Real and virtual elements that must react to each other\",\n              \"Headset or tracked camera\",\n              \"Moderate — depends on setup\"\n            ]\n          ]\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"Budget and timeline reality\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"AR is almost always the fastest and cheapest of the three to deploy at scale, since it runs on a device most of your audience already has in their pocket. VR carries hardware cost on top of build cost — every headset is a line item, and a large activation means either owning a fleet of them or renting one. Mixed reality tends to sit at the top of both budget and timeline, because it's solving two problems (a real environment and a virtual one) that have to be built to work together, not separately.\"\n        },\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"None of that means \\\"pick the cheap one.\\\" It means the format should already be decided by the outcome before cost enters the conversation — otherwise budget ends up choosing the format for you, and the outcome quietly gets smaller to fit it.\"\n        }\n      ],\n      \"navLabel\": null\n    },\n    {\n      \"type\": \"section\",\n      \"heading\": \"Questions to ask your vendor\",\n      \"blocks\": [\n        {\n          \"kind\": \"paragraph\",\n          \"richText\": \"A short list that tends to surface whether a vendor has actually thought through your brief, or is fitting your brief to whatever they already built last time:\"\n        },\n        {\n          \"kind\": \"bulletList\",\n          \"items\": [\n            \"What happens to this experience for the person who's third in line, not first?\",\n            \"What's the plan if the venue's wifi or lighting isn't what was promised?\",\n            \"Who owns the build after the event — can it be reused, or does it die with the activation?\",\n            \"What's the fallback if a headset or device fails mid-event?\"\n          ]\n        },\n        {\n          \"kind\": \"closingNote\",\n          \"body\": \"None of these questions are about the technology. They're about whether the studio has run something like this before, in a room like yours, for an audience like the one you're actually inviting. That's usually a better filter than the format name on the brief.\"\n        }\n      ],\n      \"navLabel\": null\n    }\n  ],\n  \"cta\": {\n    \"heading\": \"Still not sure which format fits?\",\n    \"body\": \"Tell us the outcome you're actually after and we'll tell you straight whether that's an AR, VR, or mixed reality brief — before you commit to a build.\"\n  },\n  \"galleryPlacement\": null\n}\n";

const galleryAccordionMeta_hbs = "<style>\n  .gallery-wrap{max-width:1180px;margin:0 auto;padding:40px 24px;}\n  @media(min-width:900px){.gallery-wrap{padding:56px 80px;}}\n\n  /* ============ ACCORDION GALLERY — drop this block into any article ============ */\n  .accordion{\n    display:flex;gap:6px;height:min(72vh,620px);border:1px solid var(--hairline);padding:6px;background:var(--surface);\n  }\n  .panel{position:relative;flex:1;overflow:hidden;cursor:pointer;transition:flex 0.6s cubic-bezier(.19,1,.22,1);min-width:44px;}\n  .accordion:not(:hover) .panel[data-default=\"true\"]{flex:6;}\n  .accordion .panel:hover{flex:6;}\n  .panel img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:grayscale(.2) contrast(1.1) brightness(.82) saturate(.95);}\n  .panel .tint{position:absolute;inset:0;background:var(--blue);opacity:.18;mix-blend-mode:multiply;}\n  .panel .scrim{position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,0) 45%, rgba(0,0,0,.85) 100%);}\n  .panel .index{position:absolute;top:14px;left:14px;font-family:'Space Grotesk',sans-serif;font-size:11px;font-weight:700;color:rgba(255,255,255,0.85);letter-spacing:0.06em;}\n  .panel .cap{position:absolute;left:14px;right:14px;bottom:14px;opacity:0;transition:opacity .3s ease .1s;white-space:nowrap;}\n  .accordion:not(:hover) .panel[data-default=\"true\"] .cap,\n  .accordion .panel:hover .cap{opacity:1;}\n  .panel .cap .tag{display:inline-block;border:1px solid var(--blue);color:var(--blue);background:rgba(10,10,10,0.6);font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;padding:3px 8px;margin-bottom:8px;}\n  .panel .cap h3{font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:19px;color:var(--white);line-height:1.25;}\n  .panel .cap p{margin-top:4px;font-size:12.5px;color:rgba(255,255,255,0.8);font-weight:300;}\n  @media(max-width:760px){\n    .accordion{flex-direction:column;height:auto;}\n    .panel{flex:none !important;height:64px;transition:height .5s ease;}\n    .accordion:not(:hover) .panel[data-default=\"true\"]{height:340px;}\n    .panel:hover, .panel:focus-within{height:340px;}\n    .panel .cap{white-space:normal;}\n  }\n</style>\n\n<div class=\"gallery-wrap\">\n  <div class=\"accordion\">\n    {{#each items}}\n    <div class=\"panel\"{{#if this.isDefault}} data-default=\"true\"{{/if}}>\n      <img src=\"{{{this.src}}}\" alt=\"placeholder\">\n      <div class=\"tint\"></div><div class=\"scrim\"></div>\n      <span class=\"index\">{{pad2 @index}}</span>\n      <div class=\"cap\"><span class=\"tag\">{{this.tag}}</span><h3>{{this.title}}</h3><p>{{this.metric}}</p></div>\n    </div>\n    {{/each}}\n  </div>\n</div>\n";
const galleryAccordionMeta_exampleJson = "{\n  \"items\": [\n    { \"imageId\": \"img-1\", \"tag\": \"AR Event\", \"title\": \"ARFestKL\", \"metric\": \"52,417 AR impressions · 12,040 QR scans\" },\n    { \"imageId\": \"img-2\", \"tag\": \"Immersive Exhibition\", \"title\": \"IKAT Malaysia\", \"metric\": \"RM3.2M media value · 5,822 visitors\" },\n    { \"imageId\": \"img-3\", \"tag\": \"AR Heritage\", \"title\": \"CheritAR\", \"metric\": \"12 countries reached · 1,442 AR impressions\" },\n    { \"imageId\": \"img-4\", \"tag\": \"AR + Immersive Room\", \"title\": \"New Balance Grey Day\", \"metric\": \"Realtime AR try-on experience\" },\n    { \"imageId\": \"img-5\", \"tag\": \"Interactive Wall\", \"title\": \"PNB 118 Stories\", \"metric\": \"Largest interactive install built for the tower\" },\n    { \"imageId\": \"img-6\", \"tag\": \"Interactive Installation\", \"title\": \"AirAsia Founders' Gallery\", \"metric\": \"Interactive walls + AR + AI, permanent install\" }\n  ]\n}\n";

